<script setup lang="ts">
import { ref } from 'vue'
import { supabase } from '../lib/supabase'
import bg from '../assets/images/bg_login_register.jfif'
import { useToast } from 'vue-toastification'

const email = ref('')
const toast = useToast()

const sendResetEmail = async () => {
    if (!email.value) {
        toast.error('请输入邮箱地址')
        return
    }

    const { error } = await supabase.auth.resetPasswordForEmail(email.value,
        {
            redirectTo: `${import.meta.env.VITE_APP_URL}/update-password`
        }
    )

    if (error) {
        toast.error(error.message)
        return
    }

    toast.success('密码重置邮件已发送，请前往邮箱查看并完成后续操作。')
}


</script>

<template>
    <div class="flex justify-center items-center h-screen bg-center bg-cover"
        :style="{ backgroundImage: `url(${bg})` }">
        <div class="flex w-100 flex-col gap-4">
            <div class="logo flex justify-center">

                <svg width="113" height="113" viewBox="0 0 113 113" fill="none" xmlns="http://www.w3.org/2000/svg"
                    xmlns:xlink="http://www.w3.org/1999/xlink">
                    <circle cx="56.5" cy="56.5" r="56.5" fill="url(#pattern0_12_9)" />
                    <defs>
                        <pattern id="pattern0_12_9" patternContentUnits="objectBoundingBox" width="1" height="1">
                            <use xlink:href="#image0_12_9" transform="translate(-0.00862069) scale(0.00431034)" />
                        </pattern>
                        <image id="image0_12_9" width="236" height="232" preserveAspectRatio="none"
                            xlink:href="data:image/png;base64," />
                    </defs>
                </svg>

            </div>
            <div class="box mx-2 flex flex-col gap-4 bg-[#EEEEEE]/90 p-10 rounded-[12px]">
                <div class="text-4xl font-normal text-center">
                    忘记密码
                </div>

                <div class="text-2xl font-normal" for="">邮箱</div>
                <input v-model="email" placeholder="example@email.com" class="bg-[#FFFFFF] px-5 py-2 rounded-[12px]" />

                <button @click="sendResetEmail" class="bg-[#DA6501] mt-2 text-white p-2 rounded-[12px] cursor-pointer">
                    提交
                </button>
            </div>
        </div>
    </div>
</template>